
$root = $PSScriptRoot
function Write-B64($b64, $path) {
    $full = Join-Path $root $path
    $dir = Split-Path $full -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
    try {
        $bytes = [System.Convert]::FromBase64String($b64)
        [System.IO.File]::WriteAllBytes($full, $bytes)
        Write-Host "OK $path" -ForegroundColor Green
    } catch {
        Write-Host "FAIL $path $_" -ForegroundColor Red
    }
}

Write-Host "Fixing backend..." -ForegroundColor Cyan
Write-B64 "" "backend\app\Services\GithubService.php"
Write-B64 "" "backend\app\Services\MapboxService.php"
Write-B64 "" "backend\app\Services\GoogleBooksService.php"
