Write-B64 "" "backend\app\Models\GoogleBook.php"
Write-B64 "" "backend\app\Http\Controllers\Api\Integrations\GithubController.php"
Write-B64 "" "backend\app\Http\Controllers\Api\Integrations\MapboxController.php"
Write-B64 "" "backend\app\Http\Controllers\Api\Integrations\GoogleBooksController.php"
