# Migrations with fixed names
Write-B64 "" "backend\database\migrations\2026_09_26_000001_create_github_repos_table.php"
Write-B64 "" "backend\database\migrations\2026_09_26_000002_create_mapbox_locations_table.php"
Write-B64 "" "backend\database\migrations\2026_09_26_000003_create_google_books_table.php"

# Patch User model
$userPath = Join-Path $root "backend\app\Models\User.php"
if (Test-Path $userPath) {
    $u = Get-Content $userPath -Raw
    if ($u -notmatch "githubRepos") {
        $u = $u -replace "HasApiTokens","HasApiTokens`n    public function githubRepos(){ return `$this->hasMany(\App\Models\GithubRepo::class); }`n    public function mapboxLocations(){ return `$this->hasMany(\App\Models\MapboxLocation::class); }`n    public function googleBooks(){ return `$this->hasMany(\App\Models\GoogleBook::class); }"
        Set-Content -Path $userPath -Value $u -Encoding UTF8
        Write-Host "Patched User.php relations" -ForegroundColor Green
    } else {
        Write-Host "User.php already has relations" -ForegroundColor Yellow
    }
}

Set-Location "$root\backend"
php artisan config:clear
